{"code": "import pandas as pd, json
df = pd.read_csv('focus_billing.csv')
def team(t):
    try: return json.loads(t).get('team')
    except: return None
df['team'] = df['Tags'].apply(team)
m = (df['team']=='payments') & (df['BillingPeriodStart'].astype(str).str.startswith('2026-09'))
print(df[m]['BilledCost'].sum().round(2))"}

